// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Write frames -- per component, the global frame constrains every
//! SystemState field outside the component's write set to be unchanged
//! across its firing; the local frame is `true`.

#![allow(non_snake_case)]

use vstd::prelude::*;

use crate::system_state::SystemState;

verus! {

/** SENSOR writes: sensedTemp, tempChanged.
  * Everything else must be unchanged.
  */
pub open spec fn sensor_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.desired_temp == post.desired_temp
  && pre.heatCmd == post.heatCmd
  && pre.setPoints == post.setPoints
  && pre.lastCmd == post.lastCmd
  && pre.heaterState == post.heaterState
}

/** SENSOR local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn sensor_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

/** OI writes: desired_temp.
  * Everything else must be unchanged.
  */
pub open spec fn oi_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.sensedTemp == post.sensedTemp
  && pre.tempChanged == post.tempChanged
  && pre.heatCmd == post.heatCmd
  && pre.setPoints == post.setPoints
  && pre.lastCmd == post.lastCmd
  && pre.heaterState == post.heaterState
}

/** OI local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn oi_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

/** THERM writes: heatCmd, setPoints, lastCmd.
  * Everything else must be unchanged.
  */
pub open spec fn therm_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.sensedTemp == post.sensedTemp
  && pre.tempChanged == post.tempChanged
  && pre.desired_temp == post.desired_temp
  && pre.heaterState == post.heaterState
}

/** THERM local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn therm_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

/** HS writes: heaterState.
  * Everything else must be unchanged.
  */
pub open spec fn hs_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.sensedTemp == post.sensedTemp
  && pre.tempChanged == post.tempChanged
  && pre.desired_temp == post.desired_temp
  && pre.heatCmd == post.heatCmd
  && pre.setPoints == post.setPoints
  && pre.lastCmd == post.lastCmd
}

/** HS local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn hs_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

} // verus!
